"""Game-engine projects and code repositories inside library folders.

Kurator never writes into library folders on its own (catalog and previews live in the data
folder). What this module adds:

* folders that are generated by tools are not indexed: Unity's Library/Temp/Logs, Unreal's
  Intermediate/Saved/DerivedDataCache, build output next to Visual Studio / CMake / Cargo
  projects, Python virtual environments. Hidden folders (.git, .godot, .import, .vs) are skipped
  anyway.
* engine_root() tells whether a file sits inside a Unity, Godot or Unreal project or a git
  repository, so optional XMP sidecars are not dropped into them (Unity would make .meta files for
  them, git would list them as new files).
"""

from __future__ import annotations

import os
from functools import lru_cache

UNITY_GENERATED = {"library", "temp", "logs", "obj", "build", "builds", "usersettings", "memorycaptures"}
UNREAL_GENERATED = {"intermediate", "saved", "deriveddatacache", "binaries", "build"}
CODE_GENERATED = {"obj", "bin", "x64", "x86", "debug", "release", "out", "build", "target", "cmake-build-debug",
                  "cmake-build-release", "node_modules", "__pycache__", "dist"}
CODE_MARKERS = (".sln", ".csproj", ".vcxproj", ".fsproj", ".vbproj")


def skip_children(names: list[str]) -> set[str]:
    """Lower-case names of sub-folders not worth indexing, given the entries of one folder."""
    low = {n.lower() for n in names}
    out: set[str] = set()
    if "assets" in low and "projectsettings" in low:
        out |= UNITY_GENERATED
    if any(n.endswith(".uproject") for n in low):
        out |= UNREAL_GENERATED
    if any(n.endswith(CODE_MARKERS) for n in low) or low & {"cmakelists.txt", "cargo.toml", "build.gradle", "pom.xml"}:
        out |= CODE_GENERATED
    return out


def skip_folder(names: list[str]) -> bool:
    """A folder whose own content is generated: a Python virtual environment."""
    return "pyvenv.cfg" in {n.lower() for n in names}


@lru_cache(maxsize=4096)
def _root_of(folder: str) -> tuple[str, str] | None:
    try:
        names = {n.lower() for n in os.listdir(folder)}
    except OSError:
        names = set()
    if "assets" in names and "projectsettings" in names:
        return "Unity", folder
    if "project.godot" in names:
        return "Godot", folder
    if any(n.endswith(".uproject") for n in names):
        return "Unreal", folder
    if ".git" in names:
        return "git", folder
    parent = os.path.dirname(folder)
    if not parent or parent == folder:
        return None
    return _root_of(parent)


def engine_root(path: str) -> tuple[str, str] | None:
    """('Unity' | 'Godot' | 'Unreal' | 'git', project folder) for a file inside one, else None."""
    return _root_of(os.path.dirname(os.path.abspath(path)))


# Files that belong to an asset and must travel with it when it moves.
COMPANION_SUFFIXES = (".meta", ".import", ".uid")   # Unity GUIDs, Godot import settings and UIDs
